    const lift=workshopLiftRuntime(),record=workshopComponentRecord(vehicle),owner=workshopVehicleOwnerMeta(vehicle),assembly=workshopDisassemblySummary(vehicle),onLift=String(lift?.vehicleId||'')===String(vehicle?.id||'');
