  function workshopScrapyardState(){state.vehicles.scrapyard=state.vehicles.scrapyard||{parts:{},soldVehicles:0,dismantledVehicles:0,revenue:0};state.vehicles.scrapyard.parts=state.vehicles.scrapyard.parts&&typeof state.vehicles.scrapyard.parts==='object'?state.vehicles.scrapyard.parts:{};return state.vehicles.scrapyard;}
