  function coopMissionProgressLabel(){const active=activeCoopMission(),record=activeCoopRecord();if(!active||!record)return null;const template=coopMissionTemplate(record.type),p=coopProgress(record),total=Math.max(1,template.steps.length);let fraction=0;if(['fishing','school','streetRace','ovalRace','firefighter'].includes(record.type)&&p.target>0)fraction=clamp(p.counter/p.target,0,.95);const percent=record.status==='completed'?100:clamp(((p.phase+fraction)/total)*100,4,98);return{title:`${template.icon} ${template.title}`,label:coopCurrentInstruction(active,record),percent};}
