  function provisionCoopFishingGear(active){if(!active||active.coopFishingGear)return;const rod=Number(state.inventory.fishingRod||0),bait=Number(state.inventory.bait||0),rodAdded=rod<1?1:0,baitAdded=Math.max(0,coopDifficulty().fish+2-bait);state.inventory.fishingRod=rod+rodAdded;state.inventory.bait=bait+baitAdded;active.coopFishingGear={rodAdded,baitAdded};if(rodAdded||baitAdded)toast('Kit de missão liberado: vara e iscas temporárias para concluir a pescaria.','good',2600);}
