  async function coopRecordEvent(kind,role='',value=1,nextPhase=null){const active=activeCoopMission(),record=activeCoopRecord();if(!active||!record||!coopTeamState(record).ok)return false;active.eventSequence=(active.eventSequence||0)+1;const id=`${active.eventSequence}-${coopUid().replace(/[^A-Za-z0-9_-]/g,'').slice(-24)}-${kind}-${Math.floor(Date.now()/1200)}`;if(active.remote){const result=await coopBackendCall('updateCoopMissionProgress',active.id,{eventId:id,kind,value,phase:nextPhase});return!!result?.ok;}const progress=active.record.progress||(active.record.progress={phase:0,counter:0,target:1,events:{}});progress.events[id]={uid:coopUid(),role:role||active.role,kind,value,createdAtClient:Date.now()};if(Number.isFinite(Number(nextPhase)))progress.phase=Math.max(progress.phase,Number(nextPhase));progress.updatedAtClient=Date.now();return true;}
  async function coopAddCounter(kind,amount=1,target=1,nextPhase=null){const active=activeCoopMission(),record=activeCoopRecord();if(!active||!coopTeamState(record).ok)return false;const competitive=['streetRace','ovalRace'].includes(record?.type)&&record.mode==='competitive',counterDelta=competitive?0:amount;if(active.remote){const result=await coopBackendCall('updateCoopMissionProgress',active.id,{eventId:`${coopUid().slice(-12)}-${kind}-${Date.now()}-${active.eventSequence=(active.eventSequence||0)+1}`,kind,value:amount,counterDelta,target,phase:nextPhase});return!!result?.ok;}const p=active.record.progress;p.counter=Math.min(999,Number(p.counter||0)+counterDelta);p.target=target;if(Number.isFinite(Number(nextPhase)))p.phase=Math.max(p.phase,Number(nextPhase));p.events[`${kind}-${Date.now()}-${active.eventSequence=(active.eventSequence||0)+1}`]={uid:coopUid(),role:active.role,kind,value:amount,createdAtClient:Date.now()};return true;}
  async function coopReserveEvent(eventId,kind,value=1,options={}){
    const active=activeCoopMission();if(!active||!coopTeamState().ok)return{ok:false,eventOwner:''};const id=String(eventId||'').replace(/[^A-Za-z0-9_-]/g,'').slice(0,80);if(!id)return{ok:false,eventOwner:''};
    if(active.remote)return await coopBackendCall('updateCoopMissionProgress',active.id,{eventId:id,kind,value,reserveEvent:true,counterDelta:Number(options.counterDelta||0),target:options.target,phase:options.phase});
    const progress=active.record.progress||(active.record.progress={phase:0,counter:0,target:1,events:{}}),existing=progress.events[id];if(existing)return{ok:existing.uid===coopUid(),eventOwner:existing.uid,progress};
    progress.events[id]={uid:coopUid(),role:active.role,kind,value,createdAtClient:Date.now()};progress.counter=Math.max(0,Number(progress.counter||0)+Math.max(0,Number(options.counterDelta||0)));if(Number.isFinite(Number(options.target)))progress.target=Math.max(1,Number(options.target));if(Number.isFinite(Number(options.phase)))progress.phase=Math.max(Number(progress.phase||0),Number(options.phase));return{ok:true,eventOwner:coopUid(),progress};
  }
