      if(Number(state.inventory.rawFish||0)<1){toast('A equipe precisa de peixe cru para assar.','warn');return false;}if(active.cookingPending)return false;active.cookingPending=true;state.inventory.rawFish--;setTimeout(async()=>{active.cookingPending=false;if(activeCoopMission()!==active){state.inventory.rawFish++;saveState(true);return;}const credited=await coopAddCounter('cooked-fish',1,coopDifficulty(record).cook);if(!credited){state.inventory.rawFish++;saveState(true);toast('A conexão mudou. Peixe devolvido; tente assar novamente.','warn');return;}state.inventory.cookedFish=(state.inventory.cookedFish||0)+1;saveState(true);toast('Peixe assado para a equipe!','good');},1800);toast('Peixe na grelha...','good');return true;
