    const setBrake=active=>{if(typeof handleActiveSportJumpControlV705==='function'&&handleActiveSportJumpControlV705(active))return;if(mobilityDriverActive()){input.mobilityBrake=!!active;input.mobilityControlSource=active?'brake':'';if(active)input.mobilityAccelerate=false;updateMobilityControlLabels();}else if(active)requestJump();};
    const holdTouch=(element,set)=>{const ids=new Set();element?.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();const first=!ids.size;ids.add(e.pointerId);safePointerCapture(element,e.pointerId);if(first)set(true);},{passive:false});for(const type of ['pointerup','pointercancel','lostpointercapture'])element?.addEventListener(type,e=>{if(!ids.delete(e.pointerId)||ids.size)return;set(false);});window.addEventListener('blur',()=>{ids.clear();set(false);});return ids;};
