      for(let radius=2;radius<=30&&!point;radius+=2)for(let i=0;i<24;i++){const angle=i*Math.PI/12,px=x+Math.cos(angle)*radius,pz=z+Math.sin(angle)*radius;if(valid(px,pz)){point={x:px,z:pz};break;}}
