  els.missionChapter.textContent=c?c.r.mode==='coop'?'MISSÃO COOPERATIVA':'MISSÃO INDIVIDUAL':'VIVER E EXPLORAR';els.missionTitle.textContent=def?def.icon+' '+def.title:'Nosso Mundo OT';
